  const keyFactors = Array.isArray(explain.key_factors)
    ? explain.key_factors.map(f => `• ${f}`).join('\n')
    : (explain.key_factors || "No key factors were provided.");

  return `FINANCIAL ANALYSIS

Company: ${explain.entity || ""}
Ticker: ${explain.ticker || ""}

DIRECT ANSWER

${explain.direct_answer || "No direct answer was provided."}

KEY FACTORS

${keyFactors}

