parameters.jsCode:
function parseJSON(value) {
  if (!value) return {};

  if (typeof value === "object") {
    return value;
  }

  if (typeof value !== "string") {
    return {};
  }

  try {
    return JSON.parse(value);
  } catch {
    return {};
  }
}


// ======================================================
// GET NODE OUTPUTS
// ======================================================

const finalNode = $("final Edit Field").first().json;

const merge = $("Merge").first().json;

const market = parseJSON(
  merge.market_output
);

const news = parseJSON(
  merge.news_output
);

const finance = parseJSON(
  merge.finance_output
);

const risk = parseJSON(
  merge.risk_output
);

const explainability = parseJSON(
  $("Explainability Agent").first().json.output
);

const finalAnalysisRaw = parseJSON(
  $("Final Analysis Agent").first().json.output
);


// ======================================================
// FINANCE DATA
// ======================================================

const financeData =
  Object.keys(finance).length > 0
    ? finance
    : {
        summary:
          explainability.financial_analysis ||
          explainability.financial_reasoning ||
          ""
      };


// ======================================================
// RISK DATA
// ======================================================

const riskData =
  Object.keys(risk).length > 0
    ? risk
    : {
        agent: "risk",

        entity:
          explainability.entity || "",

        ticker:
          explainability.ticker || "",

        overall_risk: "",

        key_risks: [],

        risk_summary:
          explainability.risk_reasoning ||
          explainability.risk_analysis ||
          ""
      };


// ======================================================
// NEWS DATA
// ======================================================

const newsData =
  Object.keys(news).length > 0
    ? news
    : {
        entity:
          explainability.entity || "",

        ticker:
          explainability.ticker || "",

        news_summary:
          explainability.news_reasoning ||
          ""
      };


// ======================================================
// MARKET DATA
// ======================================================

const marketData = {
  current_price:
    market.current_price ?? null,

  price_change:
    market.price_change ?? null,

  price_change_percent:
    market.price_change_percent ?? null,

  open:
    market.open ?? null,

  high:
    market.high ?? null,

  low:
    market.low ?? null,

  volume:
    market.volume ?? null,

  trend:
    market.trend || "",

  volatility:
    market.volatility || "",

  market_summary:
    market.market_summary || "",

  data_source:
    market.data_source ||
    "Alpha Vantage"
};


// ======================================================
// HISTORICAL DATA
// ======================================================

const historicalData =
  Array.isArray(market.historical_data)
    ? market.historical_data
    : [];


// ======================================================
// FINAL ANALYSIS
// ======================================================
//
// If Final Analysis Agent returned a real object,
// keep it.
//
// If it returned {},
// build the object from Explainability Agent.
//

let finalAnalysis;

if (
  finalAnalysisRaw &&
  Object.keys(finalAnalysisRaw).length > 0
) {
  finalAnalysis = finalAnalysisRaw;
} else {
  finalAnalysis = {
    entity:
      explainability.entity || "",

    ticker:
      explainability.ticker || "",

    market_analysis:
      explainability.market_reasoning ||
      "",

    news_analysis:
      explainability.news_reasoning ||
      "",

    financial_analysis:
      explainability.financial_analysis ||
      explainability.financial_reasoning ||
      "",

    risk_analysis:
      explainability.risk_reasoning ||
      explainability.risk_analysis ||
      "",

    overall_assessment:
      explainability.direct_answer ||
      "",

    data_quality_notes:
      explainability.uncertainties ||
      ""
  };
}


// ======================================================
// RETURN STRUCTURED DASHBOARD OBJECT
// ======================================================

return [
  {
    json: {

      // Existing formatted report
      report_text:
        finalNode.text || "",


      // Dashboard data
      dashboard: {

        // ----------------------------------------------
        // COMPANY
        // ----------------------------------------------

        company:
          explainability.entity ||
          finalAnalysis.entity ||
          market.entity ||
          "",

        ticker:
          explainability.ticker ||
          finalAnalysis.ticker ||
          market.ticker ||
          "",


        // ----------------------------------------------
        // MARKET
        // ----------------------------------------------

        market:
          marketData,


        // ----------------------------------------------
        // HISTORICAL DATA
        // ----------------------------------------------

        historical_data:
          historicalData,


        // ----------------------------------------------
        // NEWS
        // ----------------------------------------------

        news:
          newsData,


        // ----------------------------------------------
        // FINANCE
        // ----------------------------------------------

        finance:
          financeData,


        // ----------------------------------------------
        // RISK
        // ----------------------------------------------

        risk:
          riskData,


        // ----------------------------------------------
        // FINAL ANALYSIS
        // ----------------------------------------------

        final_analysis:
          finalAnalysis,


        // ----------------------------------------------
        // EXPLAINABILITY
        // ----------------------------------------------

        explainability:
          explainability
      }
    }
  }
];
